"""Original practice for the supplied Lecture 06 PDF (94 pages)."""
GROUP = {'name':'Lecture 06','title':'Evaluation & data analysis','description':'Usability tests, field studies, experiments, SUS, statistics and qualitative analysis.','kind':'lecture'}

def build_evaluation_questions():
    bank=[]
    def m(q,correct,wrong,why,pages,topic,level='application'):
        i=1+sum(x['type']=='mcq' for x in bank)
        bank.append(dict(id=f'l6-m{i:02}',group='l6',type='mcq',prompt=q,options=[correct]+wrong,correct=0,explanation=why,source=f'Lecture 06 · PDF {pages}',topic=topic,origin='lecture',level=level))
    def s(q,a,b,pages,topic,points):
        i=1+sum(x['type']=='short' for x in bank)
        bank.append(dict(id=f'l6-s{i:02}',group='l6',type='short',prompt=q,answer=[a,b],keyPoints=points,source=f'Lecture 06 · PDF {pages}',topic=topic,origin='lecture',level='application'))

    m('A team evaluates a prototype to find problems for its next iteration. What is the purpose?', 'Formative evaluation', ['Summative evaluation','Random assignment','Selective coding'], 'Formative evaluation informs changes during design; summative evaluation assesses the finished product.','p. 12','Evaluation purposes')
    m('Which activity is analytical evaluation rather than an empirical user study?', 'Inspecting an interface against heuristics without recruiting users', ['Observing participants perform tasks','Measuring user completion times','Interviewing users during a field trial'], 'Analytical methods inspect or predict interaction; empirical evaluation collects evidence from users.','pp. 5, 10–11','Evaluation approaches')
    m('A researcher teaches every step before measuring first-use learnability. What is the main problem?', 'The guidance changes what is being measured', ['Training always increases sample representativeness','Learnability cannot be studied with tasks','Guidance makes observations qualitative only'], 'Step-by-step coaching can conceal first-use difficulties; any necessary training should match the study goal and be reported.','p. 15','Test procedure')
    m('Which task prompt avoids giving away the interaction path?', 'Find and enrol in the specified course', ['Click Search, open the first result, then press Enrol','Press the green button to finish','Use the menu labelled Course Search'], 'A goal-based task lets researchers observe whether users can discover the necessary actions.','pp. 13–15','Task design')
    m('Which measure most directly addresses memorability?', 'Task performance after a specified period away from the product', ['Number of installed features','Immediate liking of the colour palette','Network capacity during download'], 'The lecture links performance after time away with remembering how to use the system.','p. 16','Usability measures')
    m('Which pairing is correct?', 'Successful task completion: effectiveness; completion time: efficiency', ['Task completion time: utility; successful completion: colour contrast','Satisfaction rating: objective speed; errors: feature count','Number of features: memorability; age: task success'], 'Effectiveness concerns achieving the goal; efficiency concerns the resources used to do so.','pp. 13, 16','Usability measures')
    m('Before recording a participant’s face and voice, what does this lecture require?', 'Written, signed consent for the recordings', ['Only permission from the software developer','Consent after publication of the video','No additional consideration because the test is academic'], 'The lecture explicitly requires written-signed consent before these recordings.','pp. 14, 17','Consent')
    m('Participants smile and say the interface is easy, but many cannot complete the task. What should be reported?', 'Both the positive attitudes and the observed task failures', ['Only the smiles because they prove effectiveness','Only the time of successful users, without mentioning failures','A conclusion that satisfaction guarantees task success'], 'Experience reports and performance evidence answer different questions and can disagree.','pp. 17–18, 22–23','Performance and experience')
    m('For a positively worded SUS item, a response of 4 contributes how many points before scaling?', '3', ['4','1','10'], 'Positive items contribute response minus 1: 4 - 1 = 3.','p. 19','SUS scoring')
    m('For a negatively worded SUS item, a response of 2 contributes how many points before scaling?', '3', ['2','0','5'], 'Negative items contribute 5 minus response: 5 - 2 = 3.','p. 19','SUS scoring')
    m('A participant’s ten converted SUS item scores sum to 30. What is the overall SUS score?', '75', ['30','12','100'], 'Multiply the converted total by 2.5: 30 × 2.5 = 75 on the 0–100 scale.','pp. 19–21','SUS scoring')
    m('Which interpretation of SUS is sound?', 'A score of 75 is a scaled usability score, not 75% task success', ['A score of 75 proves 75% of tasks succeeded','A score of 68 is the 68th percentile by definition','A score of 100 proves there are no usability problems'], 'SUS summarizes questionnaire responses; performance and percentile interpretation require separate evidence or a reference distribution.','pp. 19–23','SUS interpretation')
    m('In a comparison of old and new enrolment interfaces, which is the independent variable?', 'Which interface is used', ['The measured completion time','The number of errors observed','The participant’s satisfaction response'], 'The researcher varies interface condition and measures resulting performance or experience.','pp. 30–32','Experimental variables')
    m('In the same comparison, what is a dependent variable?', 'Time taken to complete the defined enrolment task', ['The assigned interface condition','The planned task instructions','The decision to counterbalance'], 'The dependent variable is the measured response, rather than the manipulated factor.','pp. 30–32','Experimental variables')
    m('All old-interface users receive a slow computer, while all new-interface users receive a fast one. Why is this problematic?', 'Computer performance is confounded with interface condition', ['The task is necessarily qualitative','Both conditions now have identical hardware','The independent variable has disappeared'], 'Hardware changes systematically with interface, so either factor may explain a timing difference.','pp. 28–32','Confounds')
    m('Participants are randomly allocated to use either A or B, and each uses only one. Which design is this?', 'Between-subjects design', ['Within-subjects design','Grounded theory','Content analysis'], 'Separate participant groups experience separate conditions.','pp. 35–37','Participant designs')
    m('Every participant uses both interfaces A and B. Which design is this?', 'Within-subjects design', ['Between-subjects design','Nominal classification','A field study by definition'], 'The same participants appear in both conditions, allowing within-person comparison.','pp. 35, 38–42','Participant designs')
    m('Participants are paired by relevant expertise, then one member uses A and the other B. Which design is this?', 'Matched-participants design', ['Unmatched within-subjects design','A Latin square by definition','Selective coding'], 'Matching reduces differences on selected characteristics, but cannot ensure equivalence on everything.','pp. 35, 49','Participant designs')
    m('Everyone uses A first and B second; B is faster. What alternative explanation needs attention?', 'Practice or order effects may benefit the second condition', ['The second condition must have less utility','Randomization has eliminated all alternatives','A larger monitor was necessarily used'], 'Participants may improve through prior practice or change through fatigue, regardless of interface quality.','pp. 38–46, 49','Order effects')
    m('Which procedure counterbalances two within-subject conditions?', 'Some participants use A then B; others use B then A', ['Everyone uses A then B','One participant uses only A and all others only B','The researcher hides all timing data'], 'AB/BA distributes the order of interface exposure instead of tying each interface to one position.','pp. 43–46','Counterbalancing')
    m('What does a Latin square primarily balance?', 'Each condition’s position in the sequence', ['Every possible individual difference','The number of questionnaire words','All possible interaction effects without assumptions'], 'Each condition appears once in each ordinal position; balanced variants can additionally address immediate carryover.','p. 47','Counterbalancing')
    m('What is a major benefit of within-subjects comparison?', 'Each person serves as their own comparison, reducing between-person variation', ['Order effects cannot occur','No tasks need to be defined','Every population is represented automatically'], 'Comparing the same people across conditions reduces between-person differences, but order effects still require attention.','pp. 35–49','Participant designs')
    m('What distinguishes research experiments from typical product-focused usability testing in this lecture?', 'Research emphasizes generalizable knowledge, replicability and statistical validation', ['Product tests never plan their procedure','Research experiments do not need participants','Product tests are forbidden from collecting numbers'], 'The lecture contrasts their typical purposes and rigor, not an absolute ban on overlap in methods.','pp. 24, 50','Testing versus research')
    m('Which study best reveals how people adapt a nutrition app during real grocery shopping?', 'A field study in the real shopping context', ['Only a heuristic inspection in an office','A lab task with all interruptions removed','Only counting the number of screens'], 'Field studies examine natural activity, context and appropriation of technology.','pp. 51–53','Field studies')
    m('What is appropriation in this lecture?', 'Users integrating and adapting technology to their needs and practices', ['Randomly assigning users to conditions','Multiplying a SUS total by 2.5','Calculating a sample median'], 'Appropriation concerns how technology is adopted and fitted to users’ needs, desires and culture.','p. 52','Field studies', 'concept')
    m('Which statement about acquisition method and data type is most accurate?', 'Interviews and observations can produce both qualitative and quantitative evidence', ['Every interview response is qualitative','Every questionnaire answer is a ratio measurement','Video can never be used to count errors'], 'An open comment is qualitative; a closed response or counted event can be quantitative, regardless of collection method.','pp. 57–59','Data types')
    m('Numbers 1, 2 and 3 identify unordered user groups. What scale is this?', 'Nominal', ['Ordinal','Interval','Ratio'], 'Numbers used as category labels do not establish order or equal distances.','pp. 62–63','Measurement scales')
    m('What scale describes age brackets such as 21–30 and 31–40?', 'Ordinal', ['Nominal with no ordering','Ratio merely because ages are mentioned','Interval with guaranteed equal category spacing'], 'The recorded categories are ordered; they do not retain each person’s exact age or a true-zero quantitative scale.','pp. 64, 69','Measurement scales')
    m('Which is an interval-scale example in the lecture?', 'Temperature measured in degrees Celsius', ['Task duration in seconds','Unordered country labels','A first/second/third preference ranking'], 'Celsius differences are meaningful, but its zero is conventional, so 20°C is not twice the temperature of 10°C.','pp. 65–66','Measurement scales')
    m('Why can 40 seconds be described as twice 20 seconds for task duration?', 'Duration is a ratio measure with a meaningful zero', ['All ordered categories allow ratios','Seconds are nominal identifiers','Duration has no meaningful differences'], 'Ratio scales support meaningful ratios because zero represents absence of the measured quantity.','p. 66','Measurement scales')
    m('Which statement about a single agree/disagree Likert item is defensible?', 'The responses are ordered, but equal gaps are not guaranteed', ['The response numbers automatically prove equal intervals','Strong agreement is twice agreement','The lowest category is a true absence of attitude'], 'A single ordered response item is ordinarily ordinal; numeric labels alone do not establish equal intervals.','pp. 64–68, 72','Measurement scales')
    m('Task times are 2, 2, 3, 4 and 19 seconds. Which is correct?', 'Mean = 6; median = 3; mode = 2', ['Mean = 3; median = 6; mode = 19','Mean = 2; median = 4; mode = 3','Mean = 19; median = 2; mode = 6'], 'The sum is 30, so mean is 6; the middle ordered value is 3; 2 occurs most often.','pp. 60–61','Descriptive statistics')
    m('Which choice describes variation rather than central tendency?', 'Range and standard deviation', ['Mean and median','Mode and mean','Median and mode'], 'Variation describes spread; mean, median and mode describe typical or central values.','p. 60','Descriptive statistics', 'concept')
    m('In a boxplot, what does the line inside the box usually represent?', 'The median', ['The sample mean by definition','The maximum','The number of participants'], 'The box spans the central quartiles, with a line marking the median; whisker conventions should be stated.','pp. 70–71','Data visualization')
    m('System A has a lower median task time than B for nine tested people. Which conclusion is appropriately limited?', 'The sample appears faster with A; this alone does not establish population-wide superiority', ['A is statistically superior for every population','The two systems have identical error rates','A must also have higher satisfaction'], 'The lecture explicitly limits the example conclusion to the particular sample; time alone does not prove every other quality.','p. 71','Interpreting evidence')
    m('Of 49 respondents, 30 agree and 12 strongly agree that dropping a course is easy. What proportion is positive?', '42/49, approximately 85.7%', ['30/49, approximately 61.2%','12/49, approximately 24.5%','42/100, exactly 42%'], 'Combine agree and strongly agree, then divide by the actual respondent total: 42/49.','p. 72','Percentages')
    m('Which description best fits content analysis?', 'Systematically code excerpts into categories and examine their occurrence', ['Treat every quotation as a representative population average','Discard categories before reading the data','Use only completion times and never words'], 'Categories can be predefined or emerge from data; coding provides a systematic route from excerpts to findings.','pp. 74–77','Content analysis')
    m('Two researchers code the same recordings. What does inter-rater reliability address?', 'How consistently their category assignments agree', ['Whether the interface is error-free','Whether their theory is certainly true','Whether their sample size is automatically sufficient'], 'Rater agreement concerns coding consistency; agreement alone does not prove that the interpretation is valid.','p. 74','Inter-rater reliability')
    m('A cashier mistypes a barcode after scanning fails, causing a billing dispute. What is the critical incident?', 'The failed scan followed by erroneous manual entry', ['A general claim that all customers dislike the store','The researchers’ opinion that the interface looks dated','The total number of supermarket products'], 'Critical incidents focus on specific pivotal facts rather than broad impressions of dissatisfaction.','pp. 78–79','Critical incidents')
    m('Which sequence best represents the grounded-theory coding approach shown?', 'Open: identify categories; axial: relate them; selective: integrate around a core category', ['Open: calculate SUS; axial: rank users; selective: choose a colour','Open: prove a theory; axial: ignore contradictory data; selective: stop analysis','Open: assign interfaces; axial: time tasks; selective: randomize participants'], 'Grounded theory iterates between data and analysis; codes, relationships and an integrating account develop from evidence.','pp. 80–91','Grounded theory')

    s('Distinguish formative from summative evaluation.', 'Formative evaluation finds problems during design to guide the next iteration.', 'Summative evaluation assesses the success of a finished product at the end of a design cycle.', 'p. 12','Evaluation purposes',['During design and revision','End-of-cycle assessment'])
    s('Distinguish analytical from empirical evaluation.', 'Analytical evaluation inspects or predicts interaction without observing recruited users perform tasks.', 'Empirical evaluation collects evidence from users, through usability tests or field studies.', 'pp. 5, 10–11','Evaluation approaches',['Inspection or prediction','Evidence from users'])
    s('Why should task instructions avoid teaching every action when testing learnability?', 'Step-by-step guidance conceals whether users can discover the interaction themselves.', 'Give a clear task goal and report any help or training so results remain interpretable.', 'pp. 14–15','Test procedure',['Coaching alters learnability','Goal-based prompt and reported assistance'])
    s('Give one measure each for effectiveness, efficiency and memorability.', 'Effectiveness: successful task completion; efficiency: time to complete the task.', 'Memorability: task performance after a specified period away from the system.', 'p. 16','Usability measures',['Success and time','Performance after time away'])
    s('What must happen before recording a participant’s face and voice?', 'Explain participation and the intended recording, and obtain informed consent.', 'The lecture requires written, signed consent before making face or voice recordings.', 'pp. 14, 17','Consent',['Informed participation','Written consent before recording'])
    s('Why combine task-performance data with comments and post-task ratings?', 'Performance data show task success, time and errors; comments can explain the observed difficulties.', 'Post-task ratings add perceived usability and experience, which may differ from observed performance.', 'pp. 16–18, 22–23','Performance and experience',['Behaviour and explanatory context','Perception is separate evidence'])
    s('Explain how to calculate a standard SUS score.', 'Odd positive items contribute response minus 1; even negative items contribute 5 minus response.', 'Sum the ten converted values and multiply by 2.5 for a score from 0 to 100.', 'pp. 19–20','SUS scoring',['Correct item polarity conversion','Total multiplied by 2.5'])
    s('All five positive SUS responses are 4 and all five negative responses are 2. Calculate the score.', 'Each item contributes 3: positive 4 − 1 and negative 5 − 2.', 'The total is 10 × 3 = 30; SUS = 30 × 2.5 = 75.', 'p. 19','SUS scoring',['Ten converted contributions of 3','Score is 75'])
    s('Why does SUS 75 not mean 75% of tasks were completed?', 'SUS is a scaled questionnaire score summarizing perceived usability, not observed task success.', 'Measure completion separately; use a reference distribution if interpreting SUS percentiles.', 'pp. 19–23','SUS interpretation',['Scaled attitude measure','Separate performance or percentile evidence'])
    s('Identify the independent and dependent variables in a speed comparison of interfaces A and B.', 'The independent variable is the interface condition: A or B.', 'The dependent variable is measured task-completion time for the defined task.', 'pp. 30–32','Experimental variables',['Manipulated interface','Measured time'])
    s('Old-interface users get slow computers and new-interface users get fast ones. Explain the problem and fix.', 'Hardware performance varies with interface condition, so it could explain the timing difference.', 'Use equivalent hardware across conditions or otherwise design the study to separate the two effects.', 'pp. 28–32','Confounds',['Alternative causal explanation','Control or separate hardware effect'])
    s('Compare between-subjects and within-subjects designs.', 'Between-subjects uses separate participant groups in each condition, avoiding cross-condition order effects.', 'Within-subjects uses the same people in all conditions, reducing individual variation but requiring order control.', 'pp. 35–49','Participant designs',['Separate groups and order advantage','Same people and order risk'])
    s('Explain matched-participants design and its limitation.', 'Pair participants on relevant characteristics and place members of each pair in different conditions.', 'Matching reduces selected individual differences but cannot guarantee equivalence on every factor.', 'pp. 35, 49','Participant designs',['Match relevant characteristics','Residual differences remain'])
    s('Everyone uses A before B and is faster with B. How would you address the order effect?', 'Practice or fatigue could affect the second condition independently of interface quality.', 'Counterbalance exposure by assigning some participants to AB and others to BA.', 'pp. 38–46','Counterbalancing',['Order is an alternative explanation','AB and BA allocation'])
    s('What does a Latin square contribute to a multi-condition study?', 'It places each condition once in each sequence position across the planned orders.', 'This balances position effects with fewer orders than testing every permutation; it does not remove every confound.', 'p. 47','Counterbalancing',['Each condition in every position','Reduced orders and limited control'])
    s('Why use a field study to investigate appropriation?', 'Appropriation concerns how people integrate and adapt technology within their real practices and culture.', 'Observe natural use and ask contextual questions to reveal adaptations that lab tasks may miss.', 'pp. 51–53','Field studies',['Adaptation in real practice','Natural-context evidence'])
    s('Explain why interviews and observation are not restricted to one data type.', 'Open comments and descriptions provide qualitative evidence about meaning and experience.', 'Closed responses and counted or timed actions can provide quantitative evidence from the same methods.', 'pp. 57–59','Data types',['Qualitative descriptions','Quantitative responses or counts'])
    s('Distinguish nominal, ordinal, interval and ratio scales.', 'Nominal labels categories; ordinal orders them without guaranteed equal gaps.', 'Interval has equal differences and a conventional zero; ratio adds a meaningful true zero.', 'pp. 62–66','Measurement scales',['Unordered versus ordered categories','Equal intervals versus true zero'])
    s('Why are recorded age brackets ordinal even though exact age can be ratio data?', 'Age brackets retain an order but replace exact ages with categories.', 'The recorded categories do not preserve exact differences or meaningful ratios between individuals.', 'pp. 64, 66, 69','Measurement scales',['Order is retained','Exact quantitative information is lost'])
    s('For times 2, 2, 3, 4 and 19 seconds, give the mean, median and mode.', 'Mean = 30 ÷ 5 = 6 seconds; median = the middle value, 3 seconds.', 'Mode = 2 seconds; the unusually long time raises the mean more than the median.', 'pp. 60–61','Descriptive statistics',['Mean and median correct','Mode and effect of extreme value'])
    s('The nine-person example shows lower times for A than B. State a careful conclusion.', 'This sample appears to perform the task more efficiently with A than with B.', 'The descriptive result alone does not establish statistical significance or superiority for all users.', 'p. 71','Interpreting evidence',['Sample-limited efficiency conclusion','No unsupported generalization'])
    s('Define content analysis and inter-rater reliability.', 'Content analysis systematically assigns excerpts to defined or emergent categories and examines patterns or counts.', 'Inter-rater reliability concerns how consistently different coders assign the same material to categories.', 'pp. 74–77','Content analysis',['Systematic categorization','Agreement among coders'])
    s('What distinguishes a critical incident from a general impression?', 'A critical incident is a specific, pivotal event illustrating success or failure in the activity.', 'Report the observable event and consequence, such as erroneous barcode entry causing a billing dispute.', 'pp. 78–79','Critical incidents',['Specific important event','Facts and consequence'])
    s('Distinguish open, axial and selective coding in grounded theory.', 'Open coding develops categories from data; axial coding relates categories and subcategories.', 'Selective coding integrates them around a central category while collection and analysis continue to inform each other.', 'pp. 80–91','Grounded theory',['Identify then relate categories','Integrate with iterative grounding'])
    assert sum(q['type']=='mcq' for q in bank)==40
    assert sum(q['type']=='short' for q in bank)==24
    assert all(len(q['answer'])==2 and len(' '.join(q['answer']).split())<=40 for q in bank if q['type']=='short')
    return bank
